import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        print(-1)
        return

    arr = list(map(int, data[1:n+1]))
    result = []
    for i in range(1, len(arr)):
        prev = arr[i-1]
        curr = arr[i]
        if prev != 0 and curr % prev == 0:
            result.append(curr)

    if not result:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
